import io
import os
import signal
import subprocess
import tempfile
import threading
import zipfile
from pathlib import Path
from flask import Flask, request, send_file, jsonify

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 21 * 1024 * 1024
slots = threading.BoundedSemaphore(2)
ALLOWED = {".doc", ".docx", ".odt", ".rtf", ".txt", ".xls", ".xlsx", ".ods", ".csv", ".ppt", ".pptx", ".odp"}
@app.after_request
def headers(response):
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["Referrer-Policy"] = "no-referrer"
    response.headers["Content-Security-Policy"] = "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'"
    return response

@app.get("/")
def index():
    return send_file("index.html")

@app.get("/health")
def health():
    return jsonify(status="ok")

@app.errorhandler(413)
def too_large(error):
    return jsonify(error="Please choose a file smaller than 20 MB."), 413

@app.post("/convert")
def convert():
    upload = request.files.get("file")
    if not upload or not upload.filename:
        return jsonify(error="Choose a document first."), 400
    suffix = Path(upload.filename).suffix.lower()
    if suffix not in ALLOWED:
        return jsonify(error="This file type is not supported."), 400
    if not slots.acquire(blocking=False):
        return jsonify(error="Both converters are busy. Please try again shortly."), 503
    try:
        with tempfile.TemporaryDirectory(prefix="pdf-") as temp:
            root = Path(temp)
            source = root / ("document" + suffix)
            upload.save(source)
            if source.stat().st_size == 0:
                return jsonify(error="The document is empty."), 400
            if source.stat().st_size > 20 * 1024 * 1024:
                return too_large(None)
            if zipfile.is_zipfile(source):
                with zipfile.ZipFile(source) as archive:
                    if len(archive.infolist()) > 10000 or sum(f.file_size for f in archive.infolist()) > 100 * 1024 * 1024:
                        return jsonify(error="The document expands beyond the supported size."), 400
            profile = root / "profile"
            config = profile / "user"
            config.mkdir(parents=True)
            (config / "registrymodifications.xcu").write_text('''<?xml version="1.0" encoding="UTF-8"?>
<oor:items xmlns:oor="http://openoffice.org/2001/registry"><item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="MacroSecurityLevel" oor:op="fuse"><value>3</value></prop></item><item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="DisableMacrosExecution" oor:op="fuse"><value>true</value></prop></item></oor:items>''')
            process = subprocess.Popen(["libreoffice", "-env:UserInstallation=" + profile.as_uri(), "--headless", "--nologo", "--nodefault", "--norestore", "--convert-to", "pdf", "--outdir", temp, str(source)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
            try:
                process.wait(timeout=60)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
                return jsonify(error="Conversion took too long. Try a smaller document."), 422
            output = root / "document.pdf"
            if process.returncode or not output.exists() or not output.read_bytes().startswith(b"%PDF-"):
                return jsonify(error="This document could not be converted. Check that it opens normally and is not password protected."), 422
            data = io.BytesIO(output.read_bytes())
        return send_file(data, mimetype="application/pdf", as_attachment=True, download_name="converted.pdf")
    except (OSError, zipfile.BadZipFile):
        app.logger.exception("Conversion failed")
        return jsonify(error="Conversion failed. Please try another document."), 422
    finally:
        slots.release()

